#[test]
fn sqlite_snapshot_semio_video_rejects_owner_ordinal_scalar_and_budget_corruption(){let original=project(&fixture());for change in 0..6{let mut db=original.clone();match change{0=>db.table_mut("semio_video_sample").unwrap().rows[0].values[1]=SqliteValue::Integer(999),1=>db.table_mut("semio_video_sample").unwrap().rows[0].values[2]=SqliteValue::Integer(99),2=>db.table_mut("semio_video_sample").unwrap().rows[0].values[3]=SqliteValue::Text("18446744073709551616".into()),3=>db.table_mut("semio_video_sample").unwrap().rows[0].values[4]=SqliteValue::Integer(2),4=>db.table_mut("semio_video_stream").unwrap().rows[0].values[8]=SqliteValue::Text("0".into()),_=>db.table_mut("semio_video_sample").unwrap().rows[0].values[3]=SqliteValue::Text("00".into())}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(limits, &mut |_|true, |control| fixture().to_sqlite_database(control)).is_err());assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(limits, &mut |_|true, |control| SemioVideoSnapshot::from_sqlite_database(&original,control)).is_err());assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |_|false, |control| fixture().to_sqlite_database(control)).is_err());}
#[test]
fn sqlite_snapshot_semio_video_independent_wide_scalar_query_and_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(db.query('SELECT presentation_timestamp FROM semio_video_sample WHERE stream_id=1 AND ordinal=0').get().presentation_timestamp!=='18446744073709551615'||db.query('SELECT hex(data) data FROM semio_video_sample WHERE stream_id=1 AND ordinal=0').get().data!=='0001FF')throw Error('scalar payload');db.query(\"UPDATE semio_video_sample SET presentation_timestamp='9223372036854775808' WHERE stream_id=1 AND ordinal=0\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(restored.streams[0].samples[0].pts,9223372036854775808);}

