#[test]
fn sqlite_snapshot_semio_video_bounded_native_text_binary_admission() {
    let snapshot=fixture();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"video".into()};
    let provider=<SemioVideoSnapshot as pack::snapshot::ArtifactPack>::sqlite_snapshot_codec().unwrap();
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
        semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |_|true, |control| snapshot.preflight_sqlite_snapshot_encoding(encoding,control)).unwrap();
        let database=semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |_|true, |control| snapshot.to_sqlite_database(control)).unwrap();
        let actual=semio_s_artifact_stdio_contract::testing::with_encoding(|native_owner| (provider.import)("Semio native admission",&dialect,&mut Some(database),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value;
        let expected=match encoding{SnapshotEncoding::Text=>store::io::IoPayload::Text(<SemioVideoSnapshot as pack::snapshot::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<SemioVideoSnapshot as pack::snapshot::ArtifactPack>::encode_pack(&snapshot))};assert!(actual==expected,"controlled native output differs from the authored ordinary wire");
        assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()}, &mut |_|true, |control| snapshot.preflight_sqlite_snapshot_encoding(encoding,control)).is_err());
        assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |_|false, |control| snapshot.preflight_sqlite_snapshot_encoding(encoding,control)).is_err());
    }
    let large= SemioVideoSnapshot{schema:"x".repeat(100000),..snapshot};
    assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()}, &mut |_|true, |control| large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,control)).is_err());
    assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |p|p.phase!=SqliteSnapshotPhase::EncodeNative||p.completed==0, |control| large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,control)).is_err());
}

#[test]
fn sqlite_snapshot_semio_video_explicit_controlled_native_owner(){
 use store::{pack::snapshot::ArtifactPack,pack::snapshot::ArtifactDsl};let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let expected=fixture();
 for payload in [store::io::IoPayload::Binary(expected.encode_pack()),store::io::IoPayload::Text(expected.print_dsl())]{
  let actual=semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioVideoSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap();assert!(actual==expected,"controlled native output differs from the authored ordinary wire");assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioVideoSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default()), native_owner)).is_err());assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioVideoSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:f["nativeAdmission"]["tinyBudgetBytes"].as_u64().unwrap() as usize,..SqliteDatabaseLimits::default()}), native_owner)).is_err());assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioVideoSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()}), native_owner)).is_err());
 }
 let count=f["nativeAdmission"]["collectionItems"].as_u64().unwrap() as usize;let canceled=f["nativeAdmission"]["cancelAfter"].as_u64().unwrap() as usize;let mut large=expected;large.streams.truncate(1);large.streams[0].samples=vec![SemioVideoSample{pts:u64::MAX,key:false,data:vec![0,255]};count];
 for payload in [store::io::IoPayload::Binary(large.encode_pack()),store::io::IoPayload::Text(large.print_dsl())]{let mut interior=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.total==count&&p.completed==canceled{interior=true;false}else{true}};assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioVideoSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default()), native_owner)).is_err());assert!(interior);}
}

#[test]
fn sqlite_snapshot_semio_video_controlled_native_output(){let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let mut s=fixture();s.streams[0].codec="x".repeat(f["nativeOutputBytes"].as_u64().unwrap() as usize);for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let actual=semio_s_artifact_stdio_contract::testing::with_encoding(|native_owner| s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap();let expected=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<SemioVideoSnapshot as pack::snapshot::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::io::IoPayload::Text(<SemioVideoSnapshot as pack::snapshot::ArtifactDsl>::print_dsl(&s))};assert!(actual==expected,"controlled native output differs from the authored ordinary wire");for measured in [false,true]{let mut interior=false;let error=semio_s_artifact_stdio_contract::testing::with_encoding(|native_owner| s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |event|{let cancel=event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>=65536&&(if measured{event.total==0}else{event.total>65536&&event.completed<event.total});interior|=cancel;!cancel},SqliteDatabaseLimits::default()), native_owner)).unwrap_err();assert!(interior&&error.message.contains("cancel"),"{error}");}for limits in [SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_file_bytes:4096,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_rows:0,..SqliteDatabaseLimits::default()}]{assert!(semio_s_artifact_stdio_contract::testing::with_encoding(|native_owner| s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits), native_owner)).is_err());}assert!(semio_s_artifact_stdio_contract::testing::with_encoding(|native_owner| s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default()), native_owner)).is_err());}}

#[test]
fn sqlite_snapshot_semio_video_erased_preserves_code_admitted_intermediate_owner(){
 use std::io::Write;use std::process::{Command,Stdio};
 let neutral:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🧩️intermediate/🔣️.json")).unwrap();let input=&neutral["snapshot"];
 let stream=&input["streams"][0];let snapshot=SemioVideoSnapshot{schema:input["schema"].as_str().unwrap().into(),streams:vec![SemioVideoStream{kind:SemioVideoStreamKind::Video,codec:stream["codec"].as_str().unwrap().into(),width:u32::try_from(stream["width"].as_u64().unwrap()).unwrap(),height:u32::try_from(stream["height"].as_u64().unwrap()).unwrap(),rate:SemioRational{num:stream["rate"]["num"].as_str().unwrap().parse().unwrap(),den:stream["rate"]["den"].as_str().unwrap().parse().unwrap()},samples:Vec::new()}]};
 let provider=<SemioVideoSnapshot as pack::snapshot::ArtifactPack>::sqlite_snapshot_codec().unwrap();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"video".into()};
 for encoding in [SnapshotEncoding::Text,SnapshotEncoding::Binary]{
  let payload=match encoding{SnapshotEncoding::Text=>store::io::IoPayload::Text(<SemioVideoSnapshot as pack::snapshot::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<SemioVideoSnapshot as pack::snapshot::ArtifactPack>::encode_pack(&snapshot))};
  assert_eq!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioVideoSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap(),snapshot);
  let db=semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| (provider.export)("s.stdio.semio.video",&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value;assert_eq!(restore(&db).unwrap(),snapshot);
  let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const f=JSON.parse(process.argv[1]);const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));try{if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const actualRows=db.query(f.query).all();const record=row=>{const columns=Object.keys(row).sort();return[columns,columns.map(column=>row[column])];};if(JSON.stringify(actualRows.map(record))!==JSON.stringify(f.expectedRows.map(record)))throw Error('full query');await Bun.write(Bun.stdout,db.serialize());}finally{db.close();}";
  let text=serde_json::to_string(&neutral).unwrap();let mut child=Command::new("bun").args(["-e",script,&text]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));
  let db=import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let result=semio_s_artifact_stdio_contract::testing::with_encoding(|native_owner| (provider.import)("s.stdio.semio.video",&dialect,&mut Some(db),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value;
  assert_eq!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioVideoSnapshot::decode_sqlite_snapshot_native(&result,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap(),snapshot);
 }
}

