#[test]
fn sqlite_snapshot_semio_video_complete_independent_copied_columns_admission(){
 use store::{os_store::serialization::ArtifactSqliteSnapshotHost as _,sqlite_snapshot::*};let source=fixture();let database=semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |_|true, |control| source.to_sqlite_database(control)).unwrap();let limits=SqliteDatabaseLimits{max_columns:8,..SqliteDatabaseLimits::default()};assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(limits, &mut |_|true, |control| source.to_sqlite_database(control)).is_err());assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(limits, &mut |_|true, |control| SemioVideoSnapshot::from_sqlite_database(&database,control)).is_err());for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=semio_s_artifact_stdio_contract::testing::with_encoding(|native_owner| source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap();assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(limits, &mut |_|true, |control| source.preflight_sqlite_snapshot_encoding(encoding,control)).is_err(),"preflight copied columns {encoding:?}");assert!(semio_s_artifact_stdio_contract::testing::with_encoding(|native_owner| source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits), native_owner)).is_err(),"encoder copied columns {encoding:?}");assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioVideoSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits), native_owner)).is_err(),"decoder copied columns {encoding:?}");}
}

/// 🔮️ Interprets every actual public-file cell and declared table through independent SQLite.
fn norm_independent_public_file_extent(bytes:&[u8])->serde_json::Value{use std::{io::Write,process::{Command,Stdio}};let script=concat!(include_str!("../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🧪️tests/🔮️semantic-extent/🟦️.ts"),"\nawait Bun.write(Bun.stdout,JSON.stringify(independentSqliteExtent(new Uint8Array(await Bun.stdin.arrayBuffer()))));");let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));serde_json::from_slice(&output.stdout).unwrap()
}

#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_semio_video_complete_actual_typed_public_io_limits(){
 use {semio_framework_artifact_reference::ArtifactDialect,semio_framework_os_kernel::io::io_mechanism::io_export_sqlite_snapshot,semio_framework_os_kernel::io::io_mechanism::io_import_sqlite_snapshot};use store::sqlite_snapshot::*;
 semio_framework_plugin::PluginBuilder::<_, semio_framework_plugin::app::NoPluginApp>::new("stdio").label("semioVideo complete public file scope").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap(), &[]).unwrap()).try_build().unwrap();
 let dialect=ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"video".into()};let contract:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎛️semantic.json")).unwrap();let public=&contract["publicIo"];
 for case in contract["cases"].as_array().unwrap(){let source=norm_complete_source(case);let domain=SqliteDatabaseLimits{max_rows:case["rows"].as_u64().unwrap()as usize,max_value_bytes:case["valueBytes"].as_u64().unwrap()as usize,max_schema_bytes:contract["schemaBytes"].as_u64().unwrap()as usize,max_tables:3,max_columns:9,..SqliteDatabaseLimits::default()};let expected=semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(domain, &mut |_|true, |control| source.to_sqlite_database(control)).unwrap();let public_case=public["cases"].as_array().unwrap().iter().find(|value|value["id"]==case["id"]).unwrap();
  for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let encoding_name=match encoding{SnapshotEncoding::Binary=>"binary",SnapshotEncoding::Text=>"text"};let limits=SqliteDatabaseLimits{max_rows:public_case["rows"].as_u64().unwrap()as usize,max_value_bytes:public_case["valueBytes"][encoding_name].as_u64().unwrap()as usize,max_schema_bytes:public["schemaBytes"].as_u64().unwrap()as usize,max_tables:4,max_columns:9,..domain};let file=async{let original_file_dialect=&dialect;let original_file_input=&source;let original_file_encoding=encoding;let original_file_limits=limits;let original_file_progress:&mut dyn FnMut(semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress)->bool=&mut |_|true;semio_framework_os_kernel::io::testing::with_snapshot_file_decoding(semio_framework_os_kernel::io::testing::ORIGINAL_FILE_CALLER,original_file_limits,original_file_progress,async|sqlite_control,native_owner|io_export_sqlite_snapshot(original_file_dialect,original_file_input,original_file_encoding,sqlite_control,native_owner).await).await}.await.unwrap().value;assert_eq!(&file[..16],b"SQLite format 3\0");assert_eq!(norm_independent_public_file_extent(&file),serde_json::json!({"rows":public_case["rows"],"valueBytes":public_case["valueBytes"][encoding_name],"schemaBytes":public["schemaBytes"],"tableWidths":public["tableWidths"]}));let restored=async{let original_file_dialect=&dialect;let original_file_input=&file;let original_file_limits=limits;let original_file_progress:&mut dyn FnMut(semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress)->bool=&mut |_|true;semio_framework_os_kernel::io::testing::with_snapshot_file_encoding(semio_framework_os_kernel::io::testing::ORIGINAL_FILE_CALLER,original_file_limits,original_file_progress,async|sqlite_control,native_owner|io_import_sqlite_snapshot::<SemioVideoSnapshot>(original_file_dialect,original_file_input,sqlite_control,native_owner).await).await}.await.unwrap().value;assert_eq!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |_|true, |control| restored.to_sqlite_database(control)).unwrap(),expected);
   for short in[SqliteDatabaseLimits{max_rows:limits.max_rows-1,..limits},SqliteDatabaseLimits{max_value_bytes:limits.max_value_bytes-1,..limits},SqliteDatabaseLimits{max_schema_bytes:limits.max_schema_bytes-1,..limits},SqliteDatabaseLimits{max_tables:3,..limits},SqliteDatabaseLimits{max_columns:8,..limits}]{assert!(async{let original_file_dialect=&dialect;let original_file_input=&source;let original_file_encoding=encoding;let original_file_limits=short;let original_file_progress:&mut dyn FnMut(semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress)->bool=&mut |_|true;semio_framework_os_kernel::io::testing::with_snapshot_file_decoding(semio_framework_os_kernel::io::testing::ORIGINAL_FILE_CALLER,original_file_limits,original_file_progress,async|sqlite_control,native_owner|io_export_sqlite_snapshot(original_file_dialect,original_file_input,original_file_encoding,sqlite_control,native_owner).await).await}.await.is_err());assert!(async{let original_file_dialect=&dialect;let original_file_input=&file;let original_file_limits=short;let original_file_progress:&mut dyn FnMut(semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress)->bool=&mut |_|true;semio_framework_os_kernel::io::testing::with_snapshot_file_encoding(semio_framework_os_kernel::io::testing::ORIGINAL_FILE_CALLER,original_file_limits,original_file_progress,async|sqlite_control,native_owner|io_import_sqlite_snapshot::<SemioVideoSnapshot>(original_file_dialect,original_file_input,sqlite_control,native_owner).await).await}.await.is_err());}
  }
 }
}


#[test]
fn sqlite_snapshot_semio_video_omitted_streams_preserves_original_document_default(){let source=fixture();let payload=store::io::IoPayload::Text(format!("semio stdio.semio.video.dsl v1\nschema={}",semio_s_artifact_stdio_semio_base::io::text::codec::enc_str(&source.schema)));let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:25,max_schema_bytes:865,max_tables:3,max_columns:9,..SqliteDatabaseLimits::default()};let actual=semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioVideoSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits), native_owner)).unwrap();assert_eq!(actual,SemioVideoSnapshot{schema:source.schema,streams:Vec::new()});assert_eq!(norm_independent_complete_extent(&actual)["valueBytes"],25);}
